```go
package main

import (
	"fmt"
	"regexp"
	"strings"
)

// YAMLNode represents a single YAML node.
type YAMLNode map[string]interface{}

// ParseYAML parses a YAML string into a map of YAML nodes.
func ParseYAML(input string) (YAMLNode, error) {
	if input == "" {
		return nil, fmt.Errorf("input string cannot be empty")
	}

	// Regular expression to match YAML nodes
	re := regexp.MustCompile(`\{([^\}]+)\}|\{([^\}]+)\}|\{([^\}]+)\}`)
	matches := re.FindAllString(input, -1)

	var nodes map[string]interface{}
	for _, match := range matches {
		if match == "" {
			continue
		}
		parts := strings.SplitN(match, ":", 2)
		if len(parts) != 2 {
			return nil, fmt.Errorf("invalid YAML node format: %s", match)
		}
		node, ok := nodes[parts[0]]
		if !ok {
			node = make(map[string]interface{})
			nodes[parts[0]] = node
		}
		if len(parts) == 2 {
			node = parts[1]
		}
		if node == nil {
			return nil, fmt.Errorf("invalid YAML node: %s", match)
		}
		if _, ok := node.(map[string]interface{}); !ok {
			return nil, fmt.Errorf("invalid YAML node: %s is not a map", match)
		}
	}

	return nodes, nil
}

// parseYAMLLines parses a string of YAML lines into a map of YAML nodes.
func parseYAMLLines(lines []string) (map[string]interface{}, error) {
	var nodes map[string]interface{}
	for _, line := range lines {
		if line == "" {
			continue
		}
		parts := strings.SplitN(line, ":", 2)
		if len(parts) != 2 {
			return nil, fmt.Errorf("invalid YAML line: %s", line)
		}
		node, ok := nodes[parts[0]]
		if !ok {
			node = make(map[string]interface{})
			nodes[parts[0]] = node
		}
		if len(parts) == 2 {
			node = parts[1]
		}
		if node == nil {
			return nil, fmt.Errorf("invalid YAML line: %s", line)
		}
		if _, ok := node.(map[string]interface{}); !ok {
			return nil, fmt.Errorf("invalid YAML line: %s is not a map", line)
		}
	}

	return nodes, nil
}

// getIndent returns the number of spaces to indent the YAML string.
func getIndent(s string) int {
	return len(s) + 2
}

// parseSimpleValue parses a single YAML value into a map of YAML nodes.
func parseSimpleValue(value string) interface{} {
	if value == "" {
		return nil
	}
	parts := strings.SplitN(value, ":", 2)
	if len(parts) != 2 {
		return nil
	}
	node, ok := nodes[parts[0]]
	if !ok {
		return nil
	}
	if len(parts) == 2 {
		node = parts[1]
	}
	if node == nil {
		return nil
	}
	if _, ok := node.(map[string]interface{}); !ok {
		return nil
	}
	return node
}
